using System;using System.Linq;using UnityEngine;
public static class ValidateOrganicBog {
 public static object Main(){if(!Application.isPlaying)throw new Exception("Requires Play Mode");var world=UnityEngine.Object.FindAnyObjectByType<ExplorationWorld>();var pools=world.GetComponentsInChildren<WaterVolume>().Where(w=>w.name=="Forest bog standing water").ToArray();if(pools.Length==0)throw new Exception("No bog pools in current streaming window");float minimumDepth=10;int bottoms=0;foreach(var water in pools){var p=water.transform.position;if(!WaterVolume.Sample(p-Vector3.up*.03f,out _,out var d)||Mathf.Abs(d-.03f)>.002f)throw new Exception("Bog water sample failed");bool found=false;foreach(var ground in world.GetComponentsInChildren<SoftGroundRuts>().Where(s=>s.name=="Road adventure 6")){if(ground.GetComponent<MeshCollider>().Raycast(new Ray(p+Vector3.up*2,Vector3.down),out var hit,4)){minimumDepth=Mathf.Min(minimumDepth,p.y-hit.point.y);found=true;break;}}if(!found)throw new Exception("Bog has no physical bottom");bottoms++;}if(minimumDepth<.04f)throw new Exception("Water above uncarved ground");return new{success=true,pools=pools.Length,verifiedBottoms=bottoms,minimumWaterDepth=minimumDepth};}
}
